def Find_Max_Length(lst):
    if not lst:
        return 0
    max_length = 1
    current_length = 1
    for i in range(1, len(lst)):
        if lst[i] > lst[i - 1]:
            current_length += 1
            max_length = max(max_length, current_length)
        else:
            current_length = 1
    return max_length
```

