def removezero_ip(ip):
    # Split the IP address into its components
    components = ip.split('.')

    # Remove leading zeros from each component
    for i in range(len(components)):
        if components[i] == '0':
            components[i] = ''

    # Join the components back into a single string
    return '.'.join(components)
```

